CREATE TABLE car_models (
    id                       BIGINT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                     VARCHAR(20)   NOT NULL,
    name_th                  VARCHAR(150)  NOT NULL,
    name_en                  VARCHAR(150),
    oic_code                 VARCHAR(50),
    car_make_id              BIGINT          NOT NULL REFERENCES car_makes(id),
    car_powertrain_type_id   BIGINT          REFERENCES car_powertrain_types(id),
    order_position           INT           NOT NULL DEFAULT 0,
    active_flag              BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at               TIMESTAMPTZ   NOT NULL,
    created_by                VARCHAR(100)  NOT NULL,
    updated_at                 TIMESTAMPTZ   NOT NULL,
    updated_by                  VARCHAR(100)  NOT NULL,
    version                     BIGINT        NOT NULL DEFAULT 0,
    CONSTRAINT uq_car_models_code UNIQUE (code)
);

CREATE INDEX idx_car_models_car_make_id            ON car_models(car_make_id);
CREATE INDEX idx_car_models_car_powertrain_type_id ON car_models(car_powertrain_type_id);

COMMENT ON TABLE car_models IS 'ข้อมูลอ้างอิงรุ่นรถ — code คือ car_model_id เดิม, car_powertrain_type_id เป็น NULL ทุกแถวตอน seed เพราะไฟล์ export ที่ได้รับไม่มีข้อมูล master.CarPowerType (มีแค่ FK constraint อ้างถึง) ต้อง backfill ทีหลังเมื่อได้ข้อมูลจริง';

-- seed จากข้อมูลจริง legacy master.CarModel (1829 แถว)
